a='dbo']/Check[@Name='CK_pedidos_estado']","object_type":"Check"}},{"cell_type":"markdown","source":["# [CK_usuarios_rol]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/Table[@Name='usuarios' and @Schema='dbo']/Check[@Name='CK_usuarios_rol']","object_type":"Check"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER TABLE [dbo].[usuarios]  WITH CHECK ADD  CONSTRAINT [CK_usuarios_rol] CHECK  (([rol]='ADMIN' OR [rol]='CLIENTE' OR [rol]='EMPLEADO'))\r\n","GO\r\n","ALTER TABLE [dbo].[usuarios] CHECK CONSTRAINT [CK_usuarios_rol]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/Table[@Name='usuarios' and @Schema='dbo']/Check[@Name='CK_usuarios_rol']","object_type":"Check"}},{"cell_type":"markdown","source":["# [dbo].[sp_ActualizarEstadoPedido]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ActualizarEstadoPedido' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ActualizarEstadoPedido]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n\r\n-- =============================================\r\nCREATE   PROCEDURE [dbo].[sp_ActualizarEstadoPedido]\r\n    @idPedido INT,\r\n    @nuevoEstado VARCHAR(50)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    UPDATE pedidos\r\n    SET estado = @nuevoEstado\r\n    WHERE id_pedido = @idPedido;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ActualizarEstadoPedido' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ActualizarStock]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ActualizarStock' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ActualizarStock]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\nCREATE PROCEDURE [dbo].[sp_ActualizarStock]\r\n    @id_producto INT,\r\n    @nuevo_stock INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    BEGIN TRY\r\n        IF @nuevo_stock IS NULL OR @nuevo_stock < 0\r\n        BEGIN\r\n            RAISERROR('El nuevo valor de stock no puede ser negativo.', 16, 1);\r\n            RETURN;\r\n        END\r\n\r\n        IF NOT EXISTS (SELECT 1 FROM productos WHERE id_producto = @id_producto)\r\n        BEGIN\r\n            RAISERROR('El producto a actualizar no existe.', 16, 1);\r\n            RETURN;\r\n        END\r\n\r\n        UPDATE productos\r\n        SET stock = @nuevo_stock\r\n        WHERE id_producto = @id_producto;\r\n\r\n        SELECT @id_producto AS id_producto, @nuevo_stock AS nuevo_stock, 'Stock actualizado exitosamente' AS Mensaje;\r\n    END TRY\r\n    BEGIN CATCH\r\n        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();\r\n        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();\r\n        DECLARE @ErrorState INT = ERROR_STATE();\r\n        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);\r\n    END CATCH\r\nEND;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ActualizarStock' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_AutenticacionUsuario]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_AutenticacionUsuario' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_AutenticacionUsuario]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- =============================================\r\n\r\nCREATE PROCEDURE [dbo].[sp_AutenticacionUsuario]\r\n    @correo VARCHAR(100),\r\n    @password VARCHAR(100)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    BEGIN TRY\r\n        -- 1. Validar si el correo existe\r\n        IF NOT EXISTS (SELECT 1 FROM usuarios WHERE correo = @correo)\r\n        BEGIN\r\n            RAISERROR('El correo electrónico no está registrado.', 16, 1);\r\n            RETURN;\r\n        END\r\n\r\n        -- 2. Validar si la contraseña coincide\r\n        IF NOT EXISTS (SELECT 1 FROM usuarios WHERE correo = @correo AND password = @password)\r\n        BEGIN\r\n            RAISERROR('La contraseña es incorrecta.', 16, 1);\r\n            RETURN;\r\n        END\r\n\r\n        -- 3. Si pasa las validaciones, devolver la información completa del usuario\r\n        SELECT id_usuario, nombre, correo, telefono, rol, fecha_registro\r\n        FROM usuarios \r\n        WHERE correo = @correo AND password = @password;\r\n\r\n    END TRY\r\n    BEGIN CATCH\r\n        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();\r\n        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();\r\n        DECLARE @ErrorState INT = ERROR_STATE();\r\n\r\n        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);\r\n    END CATCH\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_AutenticacionUsuario' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_CrearPedido]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_CrearPedido' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_CrearPedido]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- =============================================\r\nCREATE PROCEDURE [dbo].[sp_CrearPedido]\r\n    @nombre_cliente VARCHAR(100) = NULL,\r\n    @correo VARCHAR(100) = NULL,\r\n    @telefono VARCHAR(20) = NULL,\r\n    @metodo_pago VARCHAR(50) = NULL,\r\n    @total DECIMAL(10,2) = 0,\r\n    @codigo_pedido VARCHAR(20) = NULL OUTPUT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    BEGIN TRY\r\n        -- Generar código único de pedido\r\n        SET @codigo_pedido = 'BC-' + CAST(FLOOR(RAND() * 9000 + 1000) AS VARCHAR(10));\r\n\r\n        -- Inserción usando los nombres EXACTOS de tus columnas\r\n        INSERT INTO pedidos (codigo, total, estado, metodo_pago, fecha_pedido)\r\n        VALUES (@codigo_pedido, @total, 'Pendiente', ISNULL(@metodo_pago, 'Efectivo'), GETDATE());\r\n\r\n        SELECT @codigo_pedido AS CodigoPedido, 'Pedido registrado exitosamente' AS Mensaje;\r\n    END TRY\r\n    BEGIN CATCH\r\n        THROW;\r\n    END CATCH\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_CrearPedido' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_EliminarProducto]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_EliminarProducto' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_EliminarProducto]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n\r\n-- =============================================\r\nCREATE PROCEDURE [dbo].[sp_EliminarProducto]\r\n    @id_producto INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    BEGIN TRY\r\n        DELETE FROM productos WHERE id_producto = @id_producto;\r\n        SELECT 1 AS Exito, 'Producto eliminado correctamente' AS Mensaje;\r\n    END TRY\r\n    BEGIN CATCH\r\n        THROW;\r\n    END CATCH;\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_EliminarProducto' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_GuardarProducto]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_GuardarProducto' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_GuardarProducto]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- =============================================\r\n\r\nCREATE PROCEDURE [dbo].[sp_GuardarProducto]\r\n    @id_producto INT = NULL,\r\n    @nombre VARCHAR(150),\r\n    @categoria VARCHAR(50),\r\n    @precio DECIMAL(10,2),\r\n    @stock INT,\r\n    @descripcion TEXT = NULL,\r\n    @icono VARCHAR(500) = NULL,\r\n    @activo BIT = 1\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    BEGIN TRY\r\n        -- 1. Validar campos de texto obligatorios y no vacíos\r\n        IF @nombre IS NULL OR LTRIM(RTRIM(@nombre)) = ''\r\n        BEGIN\r\n            RAISERROR('El nombre del producto es obligatorio.', 16, 1);\r\n            RETURN;\r\n        END\r\n\r\n        IF @categoria IS NULL OR LTRIM(RTRIM(@categoria)) = ''\r\n        BEGIN\r\n            RAISERROR('La categoría es obligatoria.', 16, 1);\r\n            RETURN;\r\n        END\r\n\r\n        -- 2. Validar valores numéricos de precio y stock\r\n        IF @precio IS NULL OR @precio <= 0\r\n        BEGIN\r\n            RAISERROR('El precio debe ser un número mayor a 0.00.', 16, 1);\r\n            RETURN;\r\n        END\r\n\r\n        IF @stock IS NULL OR @stock < 0\r\n        BEGIN\r\n            RAISERROR('El stock no puede ser un número negativo.', 16, 1);\r\n            RETURN;\r\n        END\r\n\r\n        -- 3. Inserción o Actualización\r\n        IF @id_producto IS NULL OR @id_producto = 0\r\n        BEGIN\r\n            INSERT INTO productos (nombre, categoria, precio, stock, descripcion, icono, activo)\r\n            VALUES (TRIM(@nombre), TRIM(@categoria), @precio, @stock, @descripcion, @icono, @activo);\r\n\r\n            SELECT SCOPE_IDENTITY() AS id_producto, 'Producto creado exitosamente' AS Mensaje;\r\n        END\r\n        ELSE\r\n        BEGIN\r\n            IF NOT EXISTS (SELECT 1 FROM productos WHERE id_producto = @id_producto)\r\n            BEGIN\r\n                RAISERROR('El producto especificado no existe.', 16, 1);\r\n                RETURN;\r\n            END\r\n\r\n            UPDATE productos\r\n            SET nombre = TRIM(@nombre),\r\n                categoria = TRIM(@categoria),\r\n                precio = @precio,\r\n                stock = @stock,\r\n                descripcion = ISNULL(@descripcion, descripcion),\r\n                icono = ISNULL(@icono, icono),\r\n                activo = @activo\r\n            WHERE id_producto = @id_producto;\r\n\r\n            SELECT @id_producto AS id_producto, 'Producto actualizado exitosamente' AS Mensaje;\r\n        END\r\n    END TRY\r\n    BEGIN CATCH\r\n        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();\r\n        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();\r\n        DECLARE @ErrorState INT = ERROR_STATE();\r\n        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);\r\n    END CATCH\r\nEND;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_GuardarProducto' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ObtenerPedidos]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ObtenerPedidos' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ObtenerPedidos]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- =============================================\r\n\r\nCREATE   PROCEDURE [dbo].[sp_ObtenerPedidos]\r\n    @usuario_id INT = NULL -- Si es NULL trae todos los de  (Vista Empleado), si trae ID filtra por los  Cliente\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    BEGIN TRY\r\n        IF @usuario_id IS NULL\r\n        BEGIN\r\n            -- Vista para el Empleado/admin : Ver todos los pedidos\r\n            SELECT p.id_pedido, p.codigo, u.nombre AS cliente, u.telefono, p.total, p.estado, p.metodo_pago, p.fecha_pedido\r\n            FROM pedidos p\r\n            INNER JOIN usuarios u ON p.usuario_id = u.id_usuario\r\n            ORDER BY p.fecha_pedido DESC;\r\n        END\r\n        ELSE\r\n        BEGIN\r\n            -- Vista para el Cliente: Ver solo sus pedidos\r\n            SELECT p.id_pedido, p.codigo, p.total, p.estado, p.metodo_pago, p.fecha_pedido\r\n            FROM pedidos p\r\n            WHERE p.usuario_id = @usuario_id\r\n            ORDER BY p.fecha_pedido DESC;\r\n        END\r\n    END TRY\r\n    BEGIN CATCH\r\n        THROW;\r\n    END CATCH\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ObtenerPedidos' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ObtenerProductoPorId]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ObtenerProductoPorId' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ObtenerProductoPorId]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n\r\n-- =============================================\r\nCREATE PROCEDURE [dbo].[sp_ObtenerProductoPorId]\r\n    @id_producto INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT \r\n        id_producto AS idProducto,\r\n        nombre,\r\n        categoria,\r\n        precio,\r\n        stock,\r\n        descripcion,\r\n        icono,\r\n        activo\r\n    FROM productos\r\n    WHERE id_producto = @id_producto;\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ObtenerProductoPorId' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ObtenerProductos]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ObtenerProductos' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ObtenerProductos]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\nCREATE PROCEDURE [dbo].[sp_ObtenerProductos]\r\n    @soloActivos BIT = 1\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    IF @soloActivos = 1\r\n    BEGIN\r\n        SELECT id_producto AS idProducto, nombre, categoria, precio, stock, descripcion, icono, activo\r\n        FROM productos\r\n        WHERE activo = 1;\r\n    END\r\n    ELSE\r\n    BEGIN\r\n        SELECT id_producto AS idProducto, nombre, categoria, precio, stock, descripcion, icono, activo\r\n        FROM productos;\r\n    END\r\nEND;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ObtenerProductos' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ObtenerReporteVentas]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ObtenerReporteVentas' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ObtenerReporteVentas]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROCEDURE [dbo].[sp_ObtenerReporteVentas]\r\n    @FechaInicio DATETIME = NULL,\r\n    @FechaFin DATETIME = NULL\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    -- Si no se proporcionan fechas, toma las ventas de todo el historial\r\n    SELECT \r\n        COUNT(id_pedido) AS TotalPedidosEntregados,\r\n        ISNULL(SUM(total), 0) AS TotalVendido,\r\n        ISNULL(AVG(total), 0) AS TicketPromedio\r\n    FROM pedidos \r\n    WHERE estado = 'ENTREGADO'\r\n      AND (@FechaInicio IS NULL OR fecha_pedido >= @FechaInicio)\r\n      AND (@FechaFin IS NULL OR fecha_pedido <= @FechaFin);\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_ObtenerReporteVentas' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_UsuarioRegistrar]"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_UsuarioRegistrar' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_UsuarioRegistrar]    Script Date: 06/11/2026 04:25:32 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- =============================================\r\n-- =============================================\r\nCREATE PROCEDURE [dbo].[sp_UsuarioRegistrar]\r\n    @Nombre NVARCHAR(100),\r\n    @Correo NVARCHAR(100),\r\n    @Password NVARCHAR(255),\r\n    @Telefono VARCHAR(10),\r\n    @Rol VARCHAR(20) = 'cliente'\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    -- 1. Validar que ningún campo venga vacío\r\n    IF ISNULL(LTRIM(RTRIM(@Nombre)), '') = '' OR\r\n       ISNULL(LTRIM(RTRIM(@Correo)), '') = '' OR\r\n       ISNULL(LTRIM(RTRIM(@Password)), '') = '' OR\r\n       ISNULL(LTRIM(RTRIM(@Telefono)), '') = ''\r\n    BEGIN\r\n        RAISERROR('Todos los campos son obligatorios y no pueden estar vacíos.', 16, 1);\r\n        RETURN;\r\n    END\r\n\r\n    -- 2. Validar que el NOMBRE NO contenga números\r\n    IF @Nombre LIKE '%[0-9]%'\r\n    BEGIN\r\n        RAISERROR('El nombre no puede contener números.', 16, 1);\r\n        RETURN;\r\n    END\r\n\r\n    -- 3. Validar que el TELÉFONO tenga exactamente 10 dígitos numéricos\r\n    IF LEN(@Telefono) <> 10 OR @Telefono LIKE '%[^0-9]%'\r\n    BEGIN\r\n        RAISERROR('El teléfono debe tener exactamente 10 dígitos numéricos.', 16, 1);\r\n        RETURN;\r\n    END\r\n\r\n    -- 4. Validar que el correo no esté registrado previamente\r\n    IF EXISTS (SELECT 1 FROM usuarios WHERE correo = @Correo)\r\n    BEGIN\r\n        RAISERROR('El correo electrónico ya se encuentra registrado.', 16, 1);\r\n        RETURN;\r\n    END\r\n\r\n    -- 5. Registro en la tabla usuarios\r\n    INSERT INTO usuarios (nombre, correo, password, telefono, rol, fecha_registro)\r\n    VALUES (\r\n        LTRIM(RTRIM(@Nombre)),\r\n        LTRIM(RTRIM(@Correo)),\r\n        @Password,\r\n        LTRIM(RTRIM(@Telefono)),\r\n        LOWER(@Rol),\r\n        GETDATE()\r\n    );\r\n\r\n    SELECT SCOPE_IDENTITY() AS id_usuario;\r\nEND;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DanMadz\\MSSQLSERVEREXP']/Database[@Name='BuonCalice_dbo']/StoredProcedure[@Name='sp_UsuarioRegistrar' and @Schema='dbo']","object_type":"StoredProcedure"}}]}